<script>
function fillOnvif(ip,xaddr){
  resetVideoSourceForm();
  document.getElementById('cam_host').value=ip||'';
  document.getElementById('cam_onvif_url').value=xaddr||'';
  if(!document.getElementById('cam_name').value) document.getElementById('cam_name').value='Cámara '+(ip||'ONVIF');
  document.getElementById('manual-camera').scrollIntoView({behavior:'smooth',block:'start'});
}
function editVideoSource(d){
  document.getElementById('cam_id').value=d.id||0;
  document.getElementById('cam_name').value=d.name||'';
  document.getElementById('cam_host').value=d.host||'';
  document.getElementById('cam_source_kind').value=d.source_kind||'unknown';
  document.getElementById('cam_port').value=d.onvif_port||80;
  document.getElementById('cam_onvif_url').value=d.onvif_url||'';
  document.getElementById('cam_username').value=d.username_masked||'';
  document.getElementById('cam_password').value='';
  document.getElementById('cam_rtsp').value=d.rtsp_url||'';
  document.getElementById('cam_tls').checked=!!d.verify_tls;
  document.getElementById('camera-form-title').textContent='Editar '+(d.name||'fuente de video');
  document.getElementById('camera-save-btn').innerHTML='<i class="bi bi-floppy me-2"></i>Guardar cambios, probar y sincronizar';
  document.getElementById('camera-edit-cancel').style.display='inline-block';
  document.getElementById('manual-camera').scrollIntoView({behavior:'smooth',block:'start'});
}
function toggleVideoChannels(sourceId,checked){document.querySelectorAll('input[name="enabled_channels[]"][data-video-source="'+sourceId+'"]').forEach(el=>el.checked=checked);}
function resetVideoSourceForm(){
  const f=document.getElementById('video-source-form'); if(f) f.reset();
  document.getElementById('cam_id').value='0';document.getElementById('cam_port').value='80';document.getElementById('cam_source_kind').value='unknown';
  document.getElementById('camera-form-title').textContent='Agregar cámara / NVR / DVR';
  document.getElementById('camera-save-btn').innerHTML='<i class="bi bi-camera-video me-2"></i>Guardar, probar y sincronizar';
  document.getElementById('camera-edit-cancel').style.display='none';
}
</script>
